  "scenario_id": "sc-90a5be",
  "overall_assessment": "anomalies",
  "findings": [
    {
      "benefit": "IP",
      "years": [2015, 2024],
      "pattern": "drift",
      "direction": "decrease",
      "magnitude": "~1.18 baseline (2015-2020) followed by ~-0.10 to -0.13/yr decline (2021-2024), ending at 0.667",
      "confidence": 1.0,
      "evidence": [
        "ae_ip_by_year.csv: A/E consistently ~1.17-1.21 (2015-2020) then steep, sustained YoY drop to 0.667 (2024)",
        "ae_ip_termination.csv: termination A/E ~1.0 across all diagnoses, ruling out a recovery-rate shift",
        "Deviation in 2024 exceeds 10x Poisson 1/sqrt(E); empirical trend is highly significant and directionally consistent"
      ],
      "recommended_action": "Investigate IP experience drivers: check for product mix shifts, major account attrition, underwriting/eligibility rule changes, or reporting/system issues effective ~2020/2021. Split analysis by frequency vs severity and by cohort/segment. Update pricing/valuation assumptions and run trend sensitivities."
    }
  ]
}

